<?php
require_once __DIR__.'/lib/auth.php';
requireAuth();
require_once __DIR__.'/lib/workspace.php';
require_once __DIR__.'/lib/application_match.php';

$pdo=db();
$user=currentUser();
$message='';
$error='';

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!verifyCsrf($_POST['csrf']??'')){
        http_response_code(403);
        exit('Invalid request.');
    }
    try{
        $jobId=(int)($_POST['job_id']??0);
        $profileId=(int)($_POST['profile_id']??0);
        $candidateIds=array_values(array_unique(array_filter(array_map('strval',$_POST['candidate_ids']??[]))));
        $profileCheck=$pdo->prepare('SELECT id FROM wishlist_profiles WHERE id=? AND job_id=? AND user_id=?');
        $profileCheck->execute([$profileId,$jobId,$user['id']]);
        $profileId=(int)$profileCheck->fetchColumn();
        if(!$profileId){
            $jobCheck=$pdo->prepare('SELECT title FROM jobs WHERE id=?');
            $jobCheck->execute([$jobId]);
            $jobTitle=trim((string)$jobCheck->fetchColumn());
            if($jobTitle==='')throw new RuntimeException('Invalid job wishlist.');
            $pdo->prepare('INSERT INTO wishlist_profiles(job_id,user_id,name) VALUES(?,?,?) ON DUPLICATE KEY UPDATE job_id=VALUES(job_id)')->execute([$jobId,$user['id'],$jobTitle]);
            $profileCheck=$pdo->prepare('SELECT id FROM wishlist_profiles WHERE job_id=? AND user_id=? ORDER BY id LIMIT 1');
            $profileCheck->execute([$jobId,$user['id']]);
            $profileId=(int)$profileCheck->fetchColumn();
            if(!$profileId)throw new RuntimeException('Wishlist profile could not be created.');
        }

        $valid=[];
        if($candidateIds){
            $marks=implode(',',array_fill(0,count($candidateIds),'?'));
            $candidateCheck=$pdo->prepare("SELECT id FROM candidates WHERE job_id=? AND id IN ($marks)");
            $candidateCheck->execute(array_merge([$jobId],$candidateIds));
            $valid=array_column($candidateCheck->fetchAll(),'id');
        }

        $pdo->beginTransaction();
        $pdo->prepare("DELETE FROM wishlist_items WHERE profile_id=? AND disposition='wishlist'")->execute([$profileId]);
        $save=$pdo->prepare("INSERT INTO wishlist_items(profile_id,candidate_id,disposition) VALUES(?,?,'wishlist') ON DUPLICATE KEY UPDATE disposition=IF(disposition IN ('selected','blacklisted'),disposition,'wishlist')");
        foreach($valid as $candidateId)$save->execute([$profileId,$candidateId]);
        $pdo->prepare("INSERT INTO audit_events(user_id,action,entity_type,entity_id,metadata_json) VALUES(?,'wishlist.bulk_update','wishlist_profile',?,?)")->execute([$user['id'],(string)$profileId,json_encode(['job_id'=>$jobId,'wishlist_count'=>count($valid)])]);
        $pdo->commit();
        $message=count($valid).' favourites saved.';
        $_GET['job']=$jobId;
    }catch(Throwable $e){
        if($pdo->inTransaction())$pdo->rollBack();
        $error=$e->getMessage();
    }
}

$jobsStmt=$pdo->prepare("SELECT j.id,j.title,j.status,j.required_skills_json,COUNT(DISTINCT c.id) applicants,wp.id profile_id,wp.required_skills_json profile_skills,COUNT(DISTINCT CASE WHEN wi.disposition='wishlist' THEN wi.candidate_id END) wishlist_count FROM jobs j LEFT JOIN candidates c ON c.job_id=j.id LEFT JOIN wishlist_profiles wp ON wp.job_id=j.id AND wp.user_id=? LEFT JOIN wishlist_items wi ON wi.profile_id=wp.id GROUP BY j.id,j.title,j.status,j.required_skills_json,wp.id,wp.required_skills_json ORDER BY applicants DESC,j.title");
$jobsStmt->execute([$user['id']]);
$jobs=$jobsStmt->fetchAll();
$activeJobId=(int)($_GET['job']??($jobs[0]['id']??0));
$activeJob=null;$jobMap=[];
foreach($jobs as $job){$jobMap[(int)$job['id']]=$job;if((int)$job['id']===$activeJobId)$activeJob=$job;}
if(!$activeJob&&$jobs){$activeJob=$jobs[0];$activeJobId=(int)$activeJob['id'];}

$candidates=[];$favourites=[];$requiredSkills=[];
if($activeJob)$requiredSkills=json_decode($activeJob['profile_skills']?:$activeJob['required_skills_json']?:'[]',true)?:[];
$candidateStmt=$pdo->prepare('SELECT * FROM candidates WHERE job_id=? ORDER BY created_at DESC');
$candidateStmt->execute([$activeJobId]);
foreach($candidateStmt->fetchAll() as $row){
    $candidateJob=$jobMap[(int)($row['job_id']??0)]??null;
    $candidateRequired=$candidateJob?(json_decode($candidateJob['profile_skills']?:$candidateJob['required_skills_json']?:'[]',true)?:[]):[];
    $candidate=['id'=>$row['id'],'job_id'=>(int)($row['job_id']??0),'job_title'=>trim((string)($candidateJob['title']??$row['role_title'])),'name'=>$row['name'],'role'=>$row['role_title'],'email'=>$row['email'],'phone'=>$row['phone'],'country_name'=>$row['country_name'],'source'=>$row['source_name'],'stage'=>$row['stage'],'skills'=>json_decode($row['skills_json']??'[]',true)?:[],'experience'=>json_decode($row['experience_json']??'{}',true)?:[]];
    $scoringJob=$candidateJob??[];$scoringJob['required_skills_json']=json_encode($candidateRequired);$match=applicationEvidenceMatch($candidate,$scoringJob);
    $candidate['job_score']=$match['score'];$candidate['analyzed']=$match['analyzed'];$candidate['matched']=array_column(array_filter($match['mapping'],fn($item)=>$item['status']==='experience_backed'),'requirement');$candidate['review']=array_column(array_filter($match['mapping'],fn($item)=>in_array($item['status'],['skills_only','related_review'],true)),'requirement');$candidate['missing']=array_column(array_filter($match['mapping'],fn($item)=>$item['status']==='not_found'),'requirement');$candidate['benefits']=$match['preferred_matched'];$candidate['breakdown']=$match['breakdown'];$candidates[]=$candidate;
}
usort($candidates,fn($a,$b)=>(int)$b['analyzed']<=>(int)$a['analyzed']?:(($b['job_score']??-1)<=> ($a['job_score']??-1)?:strcmp($a['name'],$b['name'])));
if($activeJob&&!empty($activeJob['profile_id'])){$favStmt=$pdo->prepare('SELECT candidate_id,disposition FROM wishlist_items WHERE profile_id=?');$favStmt->execute([$activeJob['profile_id']]);foreach($favStmt->fetchAll() as $row)$favourites[$row['candidate_id']]=$row['disposition'];}
$filterSkills=[];$filterSources=[];
foreach($candidates as $candidate){foreach($candidate['skills'] as $skill)if(trim($skill)!=='')$filterSkills[mb_strtolower(trim($skill))]=trim($skill);if(trim((string)$candidate['source'])!=='')$filterSources[$candidate['source']]=$candidate['source'];}
natcasesort($filterSkills);natcasesort($filterSources);
$totalApplicants=array_sum(array_map(fn($job)=>(int)$job['applicants'],$jobs));$totalWishlist=array_sum(array_map(fn($job)=>(int)$job['wishlist_count'],$jobs));
$drawerData=[];foreach($candidates as $i=>$candidate){$exp=$candidate['experience'];$drawerData[$candidate['id']]=['name'=>$candidate['name'],'role'=>$candidate['role'],'email'=>$candidate['email']?:'Not available','phone'=>$candidate['phone']?:'Not available','country'=>$candidate['country_name']?:'Not available','source'=>$candidate['source'],'stage'=>$candidate['stage'],'score'=>$candidate['job_score'],'analyzed'=>$candidate['analyzed'],'breakdown'=>$candidate['breakdown'],'rank'=>$i+1,'matched'=>$candidate['matched'],'review'=>$candidate['review'],'missing'=>$candidate['missing'],'benefits'=>array_slice($candidate['benefits'],0,16),'months'=>(int)($exp['total_months']??0),'confidence'=>$exp['confidence']??'Not available','jobs'=>$exp['jobs']??[],'detail_url'=>'candidate_detail.php?id='.urlencode($candidate['id']),'resume_url'=>'resume_file.php?id='.urlencode($candidate['id'])];}
$activePage='dashboard';
$pageTitle='Minimal dashboard · ResumeIQ';
$pageStyles=<<<'CSS'
<style>
