click="event.stopPropagation()"></td><td class="candidate-name"><strong><?=htmlspecialchars($candidate['name'])?></strong><small><?=htmlspecialchars($candidate['email']?:'No email')?></small></td><td><?=htmlspecialchars($candidate['stage'])?></td><td><span class="rank"><?=$i<5?'TOP '.($i+1):'RESERVE '.($i-4)?></span></td><td><span class="score"><?=$candidate['analyzed']?$candidate['job_score'].'%':'Needs analysis'?></span></td><td><i class="fa-solid fa-chevron-right muted"></i></td></tr><?php endforeach?></tbody></table></div><div class="save-bar"><span class="muted"><b id="selectedCount">0</b> selected</span><button class="btn btn-primary"><i class="fa-solid fa-heart"></i> Save favourites</button></div></form><?php endif?></main></section>
