<script>
const candidateData=<?=json_encode($drawerData,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,drawer=document.getElementById('candidateDrawer'),shade=document.getElementById('drawerShade');
const esc=v=>{let d=document.createElement('div');d.textContent=v??'';return d.innerHTML},chips=(a,t='')=>a.length?'<div class="chips">'+a.map(x=>'<span class="chip '+t+'">'+esc(x)+'</span>').join('')+'</div>':'<p class="muted">None recorded.</p>';
function openCandidate(id){let c=candidateData[id];if(!c)return;drawer.dataset.id=id;drawerName.textContent=c.name;drawerRole.textContent=c.role;drawerRank.textContent='Rank '+c.rank+' · '+c.stage;gaugeValue.textContent=c.analyzed?c.score+'/100':'Needs analysis';gaugeNeedle.style.setProperty('--needle',(-180+(c.analyzed?c.score:0)*1.8)+'deg');paneOverview.innerHTML='<div class="detail-grid"><div class="detail-card"><small>Stage</small><strong>'+esc(c.stage)+'</strong></div><div class="detail-card"><small>Experience</small><strong>'+(c.months?Math.round(c.months/12*10)/10+' years':'Uncertain')+'</strong></div><div class="detail-card"><small>Location</small><strong>'+esc(c.country)+'</strong></div><div class="detail-card"><small>Source</small><strong>'+esc(c.source)+'</strong></div></div><div class="overview-timeline"><h3>Employment & education timeline</h3>'+(c.jobs.length?c.jobs.map(j=>'<div class="timeline-item"><strong>'+esc(j.start||'')+' – '+esc(j.end||'')+'</strong><br><span class="muted">'+esc(j.label||'Timeline record')+'</span></div>').join(''):'<p class="muted">No reliable dated timeline extracted.</p>')+'</div>';paneEvidence.innerHTML='<h3>Experience-backed requirements</h3>'+chips(c.matched)+'<h3>Needs recruiter review</h3>'+chips(c.review,'extra')+'<h3>Missing requirements</h3>'+chips(c.missing,'missing')+'<h3>Additional skills (not scored)</h3>'+chips(c.benefits,'extra');paneContact.innerHTML='<div class="detail-grid"><div class="detail-card"><small>Email</small><strong>'+esc(c.email)+'</strong></div><div class="detail-card"><small>Phone</small><strong>'+esc(c.phone)+'</strong></div><div class="detail-card"><small>Location</small><strong>'+esc(c.country)+'</strong></div><div class="detail-card"><small>Source</small><strong>'+esc(c.source)+'</strong></div></div>';drawerResume.href=c.resume_url;drawerDetail.href=c.detail_url;drawer.classList.add('open');shade.classList.add('open')}
function closeDrawer(){drawer.classList.remove('open');shade.classList.remove('open')}
document.querySelectorAll('[data-candidate]').forEach(r=>{r.onclick=()=>openCandidate(r.dataset.candidate);r.onkeydown=e=>{if(e.key==='Enter')openCandidate(r.dataset.candidate)}});drawerClose.onclick=closeDrawer;shade.onclick=closeDrawer;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer()});document.querySelectorAll('.drawer-tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.drawer-tabs button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.tab-pane').forEach(x=>x.classList.toggle('active',x.dataset.pane===b.dataset.tab))});const filterRows=[...document.querySelectorAll('[data-candidate]')],filterSearch=document.getElementById('filterSearch'),filterSkill=document.getElementById('filterSkill'),filterExperience=document.getElementById('filterExperience'),filterSource=document.getElementById('filterSource'),filterScore=document.getElementById('filterScore'),filterSort=document.getElementById('filterSort'),filterStage=document.getElementById('filterStage'),filterCount=document.getElementById('filterCount'),tableBody=document.querySelector('.candidate-table tbody');
filterSearch.value=new URLSearchParams(location.search).get('q')||'';
function filterCandidates(){let shown=0;filterRows.forEach(row=>{const scoreOk=filterScore.value==='0'||(filterScore.value==='analyzed'?row.dataset.analyzed==='1':row.dataset.analyzed==='1'&&+row.dataset.score>=+filterScore.value);const visible=(!filterSearch.value||row.dataset.find.includes(filterSearch.value.toLowerCase()))&&(!filterSkill.value||row.dataset.skills.includes('|'+filterSkill.value.toLowerCase()+'|'))&&+row.dataset.months>=+filterExperience.value&&(!filterSource.value||row.dataset.source===filterSource.value)&&scoreOk&&(!filterStage.value||row.dataset.stage===filterStage.value);row.hidden=!visible;if(visible)shown++});filterRows.sort((a,b)=>(+b.dataset.analyzed-+a.dataset.analyzed)||(filterSort.value==='experience_desc'?+b.dataset.months-+a.dataset.months:filterSort.value==='score_asc'?+a.dataset.score-+b.dataset.score:filterSort.value==='name_asc'?a.dataset.name.localeCompare(b.dataset.name):+b.dataset.score-+a.dataset.score)).forEach(row=>tableBody.appendChild(row));filterCount.textContent=shown+' candidates'}
[filterSearch,filterSkill,filterExperience,filterSource,filterScore,filterSort,filterStage].forEach(control=>control.addEventListener('input',filterCandidates));filterCandidates();
const boxes=[...document.querySelectorAll('.select-box')],selectedCountElement=document.getElementById('selectedCount'),updateSelected=()=>{if(selectedCountElement)selectedCountElement.textContent=boxes.filter(b=>b.checked).length};boxes.forEach(b=>b.addEventListener('change',updateSelected));updateSelected();drawerFavourite.onclick=()=>{let b=document.querySelector('input[name="candidate_ids[]"][value="'+CSS.escape(drawer.dataset.id)+'"]');if(b&&!b.disabled){b.checked=!b.checked;updateSelected()}};
</script>
